Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "background": null,
  "padding": {
    "left": 8,
    "right": 12,
    "top": 8,
    "bottom": 8
  },
  "title": {
    "subtitle": "Share of selected KEVs with attacker-friendly conditions",
    "anchor": "start",
    "font": "Segoe UI",
    "fontSize": 15,
    "fontWeight": 700,
    "color": "#F4F7FF",
    "subtitleFont": "Segoe UI",
    "subtitleFontSize": 11,
    "subtitleColor": "#8EA9C9",
    "offset": 20
  },
  "transform": [
    {
      "calculate": "isValid(datum[''Exploit Signal Rate'']) ? datum[''Exploit Signal Rate''] : 0",
      "as": "Rate"
    },
    {
      "calculate": "format(datum.Rate, ''.0%'')",
      "as": "Rate Label"
    }
  ],
  "encoding": {
    "y": {
      "field": "Signal",
      "type": "nominal",
      "sort": [
        "Remote network vector",
        "Low attack complexity",
        "No privileges required",
        "No user interaction"
      ],
      "axis": {
        "title": null,
        "domain": false,
        "ticks": false,
        "labelColor": "#F3F6FC",
        "labelFont": "Segoe UI",
        "labelFontSize": 12,
        "labelFontWeight": 600,
        "labelLimit": 190,
        "labelPadding": 14
      }
    },
    "tooltip": [
      {
        "field": "Signal",
        "type": "nominal",
        "title": "Exploit condition"
      },
      {
        "field": "Exploit Signal Rate",
        "type": "quantitative",
        "title": "Share of selected KEVs",
        "format": ".1%"
      },
      {
        "field": "Exploit Signal CVEs",
        "type": "quantitative",
        "title": "Matching KEVs",
        "format": ",.0f"
      },
      {
        "field": "Selected KEVs",
        "type": "quantitative",
        "title": "Selected KEVs",
        "format": ",.0f"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "size": 26,
        "cornerRadius": 13,
        "color": "#24344C",
        "opacity": 0.75
      },
      "encoding": {
        "x": {
          "datum": 1,
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ]
          },
          "axis": null
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "size": 26,
        "cornerRadius": 13
      },
      "encoding": {
        "x": {
          "field": "Rate",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ]
          },
          "axis": null
        },
        "color": {
          "field": "Signal",
          "type": "nominal",
          "scale": {
            "domain": [
              "Remote network vector",
              "Low attack complexity",
              "No privileges required",
              "No user interaction"
            ],
            "range": [
              "#FF2A5F",
              "#F59E0B",
              "#00DDEB",
              "#A855F7"
            ]
          },
          "legend": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": -10,
        "font": "Segoe UI",
        "fontSize": 13,
        "fontWeight": 700,
        "color": "#FFFFFF"
      },
      "encoding": {
        "x": {
          "datum": 0.99,
          "type": "quantitative"
        },
        "text": {
          "field": "Rate Label",
          "type": "nominal"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false
    }
  }
}'
